import { EdkValidationError } from "../../../elementum-entity-client/errors.js";
import { slimTokens, } from "../../catalog/index.js";
/** Explicit escape hatch used only when pull cannot recover a portable stage key. */
export function unsafeApprovalStageId(value) {
    if (value.trim() === "")
        throw new EdkValidationError("unsafeApprovalStageId requires a non-empty platform id.");
    return { __unsafe: "approvalStageId", value };
}
/** Define an app-owned approval process using the provider's dynamic-approver contract. */
export function approvalProcess(opts) {
    if ("steps" in opts) {
        throw new EdkValidationError("approvalProcess static steps are not supported; use the dynamic approver contract.");
    }
    if (opts.name.trim() === "")
        throw new EdkValidationError("approvalProcess requires a non-empty name.");
    if (!Number.isInteger(opts.numberOfDynamicApprovers) || opts.numberOfDynamicApprovers < 0) {
        throw new EdkValidationError("approvalProcess numberOfDynamicApprovers must be an integer >= 0.");
    }
    for (const field of opts.lockedFields ?? []) {
        if (field.parent !== opts.app.refName) {
            throw new EdkValidationError(`approvalProcess locked field ${JSON.stringify(field.refName)} belongs to ${JSON.stringify(field.parent)}, not app ${JSON.stringify(opts.app.refName)}.`);
        }
    }
    const payload = slimTokens({
        name: opts.name,
        ...(opts.stage !== undefined ? { stage: opts.stage } : {}),
        ...(opts.unsafeStageId !== undefined ? { stageId: opts.unsafeStageId.value } : {}),
        numberOfDynamicApprovers: opts.numberOfDynamicApprovers,
        managedByAutomation: opts.managedByAutomation ?? false,
        denyButton: opts.denyButton ?? "Deny",
        ...(opts.defaultReason !== undefined ? { defaultReason: opts.defaultReason } : {}),
        ...(opts.summary !== undefined ? { summary: opts.summary } : {}),
        approveButton: opts.approveButton ?? "Approve",
        ...(opts.exceptionButton !== undefined ? { exceptionButton: opts.exceptionButton } : {}),
        ...(opts.lockedFields !== undefined ? { lockedFieldIds: opts.lockedFields } : {}),
    });
    return {
        ref(refName) {
            return {
                __kind: "approvalChain",
                refName,
                name: opts.name,
                parent: opts.app.refName,
            };
        },
        def(refName) {
            return {
                kind: "approvalChain",
                parent: opts.app.refName,
                refName,
                payload,
                ...(opts.enabled !== undefined ? { enabled: opts.enabled } : {}),
            };
        },
    };
}
